package app.articleaudio

import android.media.AudioAttributes
import android.media.AudioFormat
import android.media.AudioTrack
import android.os.Handler
import android.os.Looper
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableFloatStateOf
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import kotlin.concurrent.thread

/**
 * Background sound under the reading. Plays while an article plays, fades in and out, and can
 * be previewed from Settings. The sound is generated by [Noise], so there are no files.
 */
object Ambient {
    private const val RATE = 22_050
    private const val PREVIEW_MS = 6_000L

    var kind by mutableStateOf("off")
        private set
    var volume by mutableFloatStateOf(0.4f)
        private set

    private val main = Handler(Looper.getMainLooper())
    @Volatile private var worker: Thread? = null
    @Volatile private var playingKind = "off"
    @Volatile private var targetGain = 0f
    @Volatile private var stopWhenSilent = false
    private val endPreview = Runnable { if (!Reader.playing) fadeOut() }

    fun init() {
        kind = Prefs.ambient
        volume = Prefs.ambientVolume
    }

    /** Called whenever reading starts or stops. */
    fun follow(playing: Boolean) {
        main.removeCallbacks(endPreview)
        if (playing && kind != "off") start(kind) else fadeOut()
    }

    /** Picks a sound from Settings and lets it be heard. */
    fun choose(newKind: String) {
        kind = newKind
        Prefs.ambient = newKind
        DebugLog.i("Background sound set to $newKind")
        if (newKind == "off") {
            fadeOut()
            return
        }
        start(newKind)
        if (!Reader.playing) {
            main.removeCallbacks(endPreview)
            main.postDelayed(endPreview, PREVIEW_MS)
        }
    }

    fun changeVolume(value: Float) {
        volume = value
        Prefs.ambientVolume = value
        if (worker != null && !stopWhenSilent) targetGain = value
    }

    /** Lets the background sound be heard briefly while the volume slider is moved. */
    fun previewVolume() {
        if (kind == "off" || Reader.playing) return
        start(kind)
        main.removeCallbacks(endPreview)
        main.postDelayed(endPreview, PREVIEW_MS)
    }

    fun fadeOut() {
        targetGain = 0f
        stopWhenSilent = true
    }

    private fun start(newKind: String) {
        playingKind = newKind
        targetGain = volume
        stopWhenSilent = false
        if (worker?.isAlive == true) return
        worker = thread(name = "ambient") { run() }
    }

    private fun run() {
        var track: AudioTrack? = null
        try {
            val minBuffer = AudioTrack.getMinBufferSize(RATE, AudioFormat.CHANNEL_OUT_MONO, AudioFormat.ENCODING_PCM_16BIT)
            track = AudioTrack.Builder()
                .setAudioAttributes(
                    AudioAttributes.Builder()
                        .setUsage(AudioAttributes.USAGE_MEDIA)
                        .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                        .build()
                )
                .setAudioFormat(
                    AudioFormat.Builder()
                        .setSampleRate(RATE)
                        .setChannelMask(AudioFormat.CHANNEL_OUT_MONO)
                        .setEncoding(AudioFormat.ENCODING_PCM_16BIT)
                        .build()
                )
                .setBufferSizeInBytes(maxOf(minBuffer, 8_192))
                .setTransferMode(AudioTrack.MODE_STREAM)
                .build()
            track.setVolume(0f)
            track.play()
            var noiseKind = playingKind
            var noise = Noise(noiseKind, RATE, seed = System.nanoTime().toInt())
            val buffer = ShortArray(2_048)
            var gain = 0f
            while (true) {
                if (playingKind != noiseKind) {
                    noiseKind = playingKind
                    noise = Noise(noiseKind, RATE, seed = System.nanoTime().toInt())
                }
                // Move the volume a little each buffer, so starts and stops fade over a second or two.
                val step = 0.02f
                gain = if (gain < targetGain) minOf(targetGain, gain + step) else maxOf(targetGain, gain - step)
                track.setVolume(gain)
                if (stopWhenSilent && gain <= 0f) break
                noise.fill(buffer)
                track.write(buffer, 0, buffer.size)
            }
        } catch (t: Throwable) {
            DebugLog.e("Background sound failed", t)
        } finally {
            try { track?.stop() } catch (t: Throwable) { /* already stopped */ }
            try { track?.release() } catch (t: Throwable) { /* already released */ }
            worker = null
            // A new sound may have been asked for just as this one finished fading.
            if (!stopWhenSilent && targetGain > 0f) main.post { start(playingKind) }
        }
    }
}
